() => {
  const article = document.querySelector('article') || document.body;
  const text = article.innerText || '';
  const lines = text.split('\n').map(s => s.trim()).filter(Boolean);
  const countries = [];
  const look = ['China', 'Hong Kong', 'Macau', 'Macao', 'Taiwan', 'Singapore', 'Japan', 'United States'];
  const hits = {};
  for (const k of look) {
    const re = new RegExp('\\b' + k.replace(' ', '\\s+') + '\\b', 'i');
    hits[k] = re.test(text);
  }
  return {
    title: document.title,
    url: location.href,
    hits,
    preview: lines.slice(0, 40),
    countryBlock: lines.slice(20, 80)
  };
}

